add("de","A2","Deyimler","Können Sie das buchstabieren?","bunu heceleyebilir misiniz?","Ausdruck","Können Sie Ihren Namen buchstabieren?","Adınızı heceleyebilir misiniz?");
add("de","A2","Deyimler","Sprechen Sie langsamer, bitte","lütfen daha yavaş konuşun","Ausdruck","Sprechen Sie bitte etwas langsamer.","Lütfen biraz daha yavaş konuşun.");
add("de","A2","Deyimler","Können Sie das wiederholen?","bunu tekrarlayabilir misiniz?","Ausdruck","Entschuldigung, können Sie das wiederholen?","Affedersiniz, bunu tekrarlayabilir misiniz?");
add("de","A2","Deyimler","Ich habe nicht verstanden","anlamadım","Ausdruck","Entschuldigung, ich habe nicht verstanden.","Affedersiniz, anlamadım.");
add("de","A2","Deyimler","Können Sie das auf Englisch sagen?","bunu İngilizce söyleyebilir misiniz?","Ausdruck","Können Sie das bitte auf Englisch sagen?","Lütfen bunu İngilizce söyleyebilir misiniz?");
add("de","A2","Deyimler","Wie sagt man das auf Deutsch?","bu Almanca nasıl söylenir?","Ausdruck","Wie sagt man 'Danke' auf Deutsch?","Almanca 'teşekkürler' nasıl söylenir?");
add("de","A2","Deyimler","Was bedeutet das auf Türkisch?","bu Türkçe ne demek?","Ausdruck","Was bedeutet dieses Wort auf Türkisch?","Bu kelime Türkçe ne demek?");
add("de","A2","Deyimler","Ich lerne noch Deutsch","hâlâ Almanca öğreniyorum","Ausdruck","Entschuldigung, ich lerne noch Deutsch.","Affedersiniz, hâlâ Almanca öğreniyorum.");
